import React from 'react';
import classes from './NavigationItems.module.css';
import NavigationItem from './NavigationItem/NavigationItem';

const navigationItems = () => (
    <ul class="nav navbar-nav navbar-sm">

            <NavigationItem link="/" exact >Home</NavigationItem>
            <NavigationItem link="/tutorial" exact>Tutorial</NavigationItem>
            <NavigationItem link="/marketplace" exact>Marketplace</NavigationItem>
            <NavigationItem link="/profile" exact>Profile</NavigationItem>

    </ul>
);

export default navigationItems;
